import { createRouter, createWebHashHistory } from 'vue-router';
import HomePage from '@/pages/HomePage/HomePage.vue';
import ProjectPage from '@/pages/ProjectPage/ProjectPage.vue';
import MapPage from '@/pages/MapPage/MapPage.vue';

const routes = [
    { path: '/', name: 'Home', component: HomePage },
    { path: '/project/:id', name: 'Project', component: ProjectPage, props: true },
    { path: '/map', name: 'Map', component: MapPage, props: true }
];

const router = createRouter({
    history: createWebHashHistory(),
    routes,
    scrollBehavior(to, from, savedPosition) {
        if (savedPosition) {
            return savedPosition;
        }
        return { top: 0 };
    },
});

export default router;