<template>
  <div class="content" style="padding: 100px 0 200px">
    <div class="wrapper">
      <div v-if="project" class="wrapper-direction" style="display: flex;flex-direction: column;align-items: center">
        <h1 style="margin-bottom: 30px">Проект: {{ project.name }}</h1>
        <img style="margin-bottom: 30px" v-if="project.img" :src="project.img" alt="" />
        <p>Тип: {{ project.type }}</p>
        <p>Адреса: {{ project.adress }}</p>
        <router-link class="footer-info__btn" to="/">Назад</router-link>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { useRoute } from 'vue-router';

const route = useRoute();
const project = ref(null);

onMounted(async () => {
  const res = await fetch('https://test.smarto.agency/smarto_complexes_list.json');
  const data = await res.json();
  project.value = data.find(p => p.id == route.params.id);
});
</script>
