<template>
  <div class="content">
    <div class="wrapper">
      <div class="tabs">
        <!-- кнопки -->
        <div class="tabs-box">
          <div class="tabs__buttons">
            <button
                v-for="tab in tabs"
                :key="tab.id"
                class="tab-btn"
                :class="{ active: activeTab === tab.id }"
                @click="changeTab(tab.id)"
            >
              {{ tab.label }}
            </button>
          </div>
          <div class="tag-filter">
            <label class="tab-btn">Фільтр за тегом:</label>
            <select v-model="activeTag">
              <option value="">Всі</option>
              <option v-for="tag in allTags" :key="tag" :value="tag">{{ tag }}</option>
            </select>
          </div>
        </div>
        <!-- контент -->
        <div class="tabs__content">
          <div
              v-for="tab in tabs"
              :key="tab.id + '-content'"
              class="tab-content"
              :class="{ active: activeTab === tab.id }"
          >
            <div class="content-box">
              <div
                  v-for="project in visibleProjects(tab.id)"
                  :key="project.name"
                  class="content-box__item"
              >
                <div class="content-box__top">
                  <div class="content-box__date">{{ project.year }}</div>
                  <span
                      class="content-box__section"
                      @click="changeTabByType(project.type)"
                  >
                    {{ project.type }}
                  </span>
                </div>
                <router-link v-if="project.img" :to="`/project/${project.id}`" class="content-box__img">
                  <img :src="project.img" alt="" />
                </router-link>
                <router-link
                    :to="`/project/${project.id}`"
                    class="content-box__title"
                >
                  {{ project.name }}
                </router-link>
                <div v-if="project.adress" class="content-box__adress">{{ project.adress }}</div>
                <div class="content-box__types-box" v-if="project.tags && project.tags.length">
                  <span>Види робіт:</span>
                  <div class="content-box__types">
                    <span
                        v-for="tag in project.tags"
                        :key="tag"
                        class="content-box__type"
                        @click="setActiveTag(tag)"
                    >
                      {{ tag }}
                    </span>
                  </div>
                </div>
              </div>

            </div>
            <div class="btn-center">
              <button
                  v-if="canLoadMore(tab.id)"
                  class="download-btn"
                  @click="loadMore(tab.id)"
              >
                Завантажити ще
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, reactive, onMounted, computed } from 'vue'
import { useProjectsStore } from '@/stores/project'

const tabs = [
  { id: 'tab1', label: 'Усі' },
  { id: 'tab2', label: 'Comfort' },
  { id: 'tab3', label: 'Premium' },
  { id: 'tab4', label: 'Бізнес' }
]

const activeTab = ref('tab1')
const activeTag = ref('')
const currentIndex = reactive({ tab1: 0, tab2: 0, tab3: 0, tab4: 0 })
const perPage = 3

const tabTypes = {
  tab1: 'Усі',
  tab2: 'Comfort',
  tab3: 'Premium',
  tab4: 'Бізнес'
}

const store = useProjectsStore()

onMounted(() => {
  store.fetchProjects()
})

function changeTabByType(type) {
  const tab = tabs.find(t => tabTypes[t.id] === type)
  if (tab) {
    changeTab(tab.id)
  }
}
const allTags = computed(() => {
  const tagsSet = new Set()
  store.projects.forEach(p => p.tags?.forEach(tag => tagsSet.add(tag)))
  return Array.from(tagsSet)
})
function setActiveTag(tag) {
  activeTag.value = tag
}
function changeTab(tabId) {
  activeTab.value = tabId
  currentIndex[tabId] = 0
  activeTag.value = ''
}

function filteredProjects(tabId) {
  const type = tabTypes[tabId]
  return store.projects.filter(p => {
    const typeMatch = type === 'Усі' || p.type === type
    const tagMatch = !activeTag.value || p.tags?.includes(activeTag.value)
    return typeMatch && tagMatch
  })
}


function visibleProjects(tabId) {
  return filteredProjects(tabId).slice(0, currentIndex[tabId] + perPage)
}

function loadMore(tabId) {
  currentIndex[tabId] += perPage
}

function canLoadMore(tabId) {
  return visibleProjects(tabId).length < filteredProjects(tabId).length
}
</script>

<style lang="scss" scoped>
@import './src/components/AppContent/AppContent';
</style>