<template>
  <div class="container">
    <div class="wrapper">
      <div class="map-container">
        <h1>Карта</h1>
        <div id="map" ref="mapRef"></div>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import L from 'leaflet';
import 'leaflet/dist/leaflet.css';

const mapRef = ref(null);

onMounted(() => {
  const map = L.map(mapRef.value).setView([50.4501, 30.5234], 12); // Центр: Київ

  L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
    attribution: '&copy; OpenStreetMap contributors'
  }).addTo(map);

  L.marker([50.4501, 30.5234])
      .addTo(map)
      .bindPopup('Smarto')
      .openPopup();
});
</script>

<style scoped>
.map-container {
  width: 100%;
  height: 500px;
  padding: 50px 0 200px;
}
h1{
  text-align: left;
  margin-bottom: 30px;
}
#map {
  width: 100%;
  height: 100%;
}
</style>